 return f'''<article class="product-card" data-search="{e(p['name'].lower())}"><div class="product-image tone-{i%4}"><span class="card-index">№ {i+1:02}</span>{img(p['image'],p['name'])}<button class="round-button" data-order="{e(p['name'])}" aria-label="Заказать {e(p['name'])}">↗</button></div><div class="product-meta"><span>Зерновой набор</span><span>25 л</span></div><h3>{e(p['name'])}</h3><div class="product-bottom"><strong>{p['price']:,} ₽</strong><a href="{e(p['video'])}" target="_blank" rel="noopener" aria-label="Смотреть видео: {e(p['name'])}">▷ Видео</a></div></article>'''.replace(',',' ')
